def _find_repo_root():
    in_file = '__file__' in globals()
    start = (Path(__file__).parent if in_file else Path.cwd()).resolve()
    is_root = lambda p: (p/'pyproject.toml').is_file() or (p/'CRAFT.js').is_file()
    return next((p for p in (start, *start.parents) if is_root(p)), start.parent if in_file else start)

REPO_ROOT = _find_repo_root()
DEFAULT_AUTH_FILE = REPO_ROOT/'.auth'/'solveit-state.json'
DEFAULT_CONFIG_FILE = REPO_ROOT/'.auth'/'config.json'
